/* Genatrix. Design 06: the job is to be trusted, not to be pretty; and a
   page that is a pleasure to be in is trusted more readily. Phone first.

   The palette is Chinese ink painting, five colours: 墨黑 #2B2B2B (ink),
   淡墨黑 #B8B8B8 (diluted ink), 宣纸白 #F7F0E8 (rice paper), 砚石灰 #6E756E
   (inkstone) and 梅红 #C83C3C (plum red). Four of them carry almost no
   colour and make one even ramp of value, 29 / 55 / 78 / 96; the fifth is
   the only colour on the page.

   Two rules follow from the painting. Plum red is the seal, not the brush:
   it marks what to look at (the name, where you are, what is waiting, the
   step you are on, what is secret, what deletes) and it is never the colour
   of an ordinary action, because red already means danger here and a red
   "Approve and send" would read as one. The main action is ink. And paper
   is paper: the ground is the rice paper itself, a card is the same paper a
   little lighter, never a cold white laid on top.

   Text is never lighter than 4.5:1. Inkstone and plum red fall just short
   on rice paper (4.19 and 4.46), so text uses each one step deeper on the
   same hue, and the colours themselves stay for marks and fills. Diluted
   ink is 1.76:1 and is only ever a line.

   One type scale, 11 / 13 / 15 / 18 / 24 / 34, with nothing in between.
   Nothing here is fetched from anywhere: system fonts, inline icons. */

@import "tailwindcss";

@theme {
  --font-sans: ui-sans-serif, -apple-system, "SF Pro Text", "Helvetica Neue", "PingFang SC", "Hiragino Sans GB", "Noto Sans CJK SC", sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, monospace;

  /* The five, by name, for anything that wants the exact colour. */
  --color-mo: #2b2b2b;
  --color-danmo: #b8b8b8;
  --color-xuan: #f7f0e8;
  --color-yan: #6e756e;
  --color-meihong: #c83c3c;

  --radius-card: 16px;
  --radius-control: 10px;
}

/* Semantic tokens that follow light and dark; `inline` makes the utilities
   read the variable at paint time. */
:root {
  /* Paper: 宣纸白 and the same paper lighter and a little deeper. */
  --bg: #f7f0e8;
  --bg-tint: radial-gradient(1100px 520px at 10% -12%, rgba(110, 117, 110, 0.10), transparent 62%),
             radial-gradient(900px 480px at 104% 2%, rgba(255, 255, 255, 0.55), transparent 58%);
  --surface: #fcf9f5;
  --surface-2: #f9f4ef;
  /* Ink: 墨黑, and 砚石灰 one step deeper for secondary text. */
  --ink: #2b2b2b;
  --muted: #555c55;
  --faint: #636a63;
  /* Lines: a wash of diluted ink; 淡墨黑 itself for the strong one. */
  --line: #e1dbd5;
  --line-strong: #b8b8b8;
  --line-warm: #ddd4c9;
  /* The seal: 梅红, and one step deeper for red text. */
  --accent: #c83c3c;
  --accent-ink: #af2f30;
  --accent-soft: #fae6e4;
  --accent-line: #efbcb7;
  /* The main action is ink, with paper on it. */
  --accent-fill: #2b2b2b;
  --accent-fill-deep: #161616;
  --on-accent: #f7f0e8;
  --badge: #c83c3c;
  /* The one field of colour, Today's: an ink wash toward inkstone. */
  --hero-from: #2b2b2b;
  --hero-to: #383c38;
  --on-hero: #f7f0e8;
  --sand: #f7f0e8;
  --sand-soft: #f9f4ef;
  /* Levels: inkstone for what is public, ink for what is personal, the
     seal for what is secret. */
  --public: #576957;
  --personal: #484848;
  --secret: #af2f30;
  --shadow: 0 1px 1px rgba(43, 43, 43, 0.05), 0 8px 20px -12px rgba(43, 43, 43, 0.30);
  --shadow-lift: 0 2px 4px rgba(43, 43, 43, 0.06), 0 20px 44px -24px rgba(43, 43, 43, 0.45);
  --bar-h: 60px;
  --safe-b: env(safe-area-inset-bottom, 0px);
}
@media (prefers-color-scheme: dark) {
  :root {
    /* At night the ink is the ground and the paper is the writing. */
    --bg: #151312;
    --bg-tint: radial-gradient(1100px 520px at 10% -12%, rgba(110, 117, 110, 0.14), transparent 62%),
               radial-gradient(900px 480px at 104% 2%, rgba(247, 240, 232, 0.04), transparent 58%);
    --surface: #201e1c;
    --surface-2: #282623;
    --ink: #ebe5de;
    --muted: #b8b8b8;
    --faint: #939b93;
    --line: #343230;
    --line-strong: #4e4d4b;
    --line-warm: #343230;
    --accent: #df6862;
    --accent-ink: #df6862;
    --accent-soft: #3a211f;
    --accent-line: #683834;
    /* The main action is paper, with ink on it. */
    --accent-fill: #ebe5de;
    --accent-fill-deep: #f7f0e8;
    --on-accent: #2b2b2b;
    --badge: #c83c3c;
    --hero-from: #32302d;
    --hero-to: #222522;
    --on-hero: #ebe5de;
    --sand: #d2c7b8;
    --sand-soft: #282623;
    --public: #97ab98;
    --personal: #c4c4c4;
    --secret: #df6862;
    --shadow: 0 1px 1px rgba(0, 0, 0, 0.35), 0 8px 20px -12px rgba(0, 0, 0, 0.7);
    --shadow-lift: 0 2px 4px rgba(0, 0, 0, 0.4), 0 20px 44px -24px rgba(0, 0, 0, 0.85);
  }
}
@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-ink: var(--ink);
  --color-muted: var(--muted);
  --color-faint: var(--faint);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-line-warm: var(--line-warm);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-accent-soft: var(--accent-soft);
  --color-accent-line: var(--accent-line);
  --color-accent-fill: var(--accent-fill);
  --color-on-accent: var(--on-accent);
  --color-sand: var(--sand);
  --color-sand-soft: var(--sand-soft);
  --color-public: var(--public);
  --color-personal: var(--personal);
  --color-secret: var(--secret);
}

@layer base {
  html, body { @apply m-0 bg-bg text-ink; }
  body {
    @apply font-sans text-[15px] leading-[1.6] antialiased;
    font-variant-numeric: tabular-nums;
    background-image: var(--bg-tint);
    background-repeat: no-repeat;
    background-attachment: fixed;
    -webkit-text-size-adjust: 100%;
    overscroll-behavior-y: none;
  }
  button, input, select, textarea { font: inherit; color: inherit; }
  button { cursor: pointer; }
  input:focus-visible, select:focus-visible, textarea:focus-visible, button:focus-visible {
    outline: 2px solid var(--ink); outline-offset: 2px;
  }
  ::selection { background: var(--accent-soft); }
}

@layer components {
  /* ---- shell ---- */
  .shell { @apply grid min-h-dvh grid-cols-1 grid-rows-[auto_1fr]; }
  .top {
    @apply sticky top-0 z-30 flex flex-col gap-0.5 px-4 pt-3 pb-2;
    background: color-mix(in srgb, var(--bg) 88%, transparent);
    backdrop-filter: saturate(1.6) blur(16px);
    -webkit-backdrop-filter: saturate(1.6) blur(16px);
    border-bottom: 1px solid var(--line-warm);
  }
  .top h1 { @apply m-0 flex items-center gap-2.5 text-[18px] font-semibold tracking-[-0.02em]; }
  .brand { @apply inline-flex items-center gap-2 font-semibold text-ink; }
  /* The mark (assets/brand): only the dot is loud. */
  .mark { @apply h-[14px] w-auto shrink-0; fill: var(--ink); }
  .mark .dot { fill: var(--accent); }
  .page-title { @apply font-medium text-muted; }
  .status { @apply m-0 truncate text-[13px] text-faint; }

  main { @apply min-w-0 px-5 pt-4 pb-[calc(var(--bar-h)+var(--safe-b)+32px)]; }
  .pane { @apply max-w-[860px]; }

  .rail { @apply hidden; }
  .bar {
    @apply fixed inset-x-0 bottom-0 z-40 grid grid-cols-5;
    border-top: 1px solid var(--line-warm);
    height: calc(var(--bar-h) + var(--safe-b));
    padding-bottom: var(--safe-b);
    background: color-mix(in srgb, var(--surface) 92%, transparent);
    backdrop-filter: saturate(1.6) blur(18px);
    -webkit-backdrop-filter: saturate(1.6) blur(18px);
  }
  .nav {
    @apply relative flex flex-col items-center justify-center gap-0.5 border-0 bg-transparent text-[11px] font-medium text-muted transition-colors;
    -webkit-tap-highlight-color: transparent;
  }
  .nav.is-on { @apply text-ink; }
  .bar .nav.is-on::before {
    content: ""; @apply absolute rounded-full;
    inset: 4px 12px auto; height: 3px; background: var(--accent);
  }
  .nav .badge { @apply absolute top-1.5 right-[calc(50%-22px)]; }
  .more-sheet {
    @apply fixed inset-x-3 z-50 grid gap-0.5 rounded-card border border-line bg-surface p-1.5;
    bottom: calc(var(--bar-h) + var(--safe-b) + 10px);
    box-shadow: var(--shadow), 0 20px 50px -20px rgba(0,0,0,0.35);
  }
  .more-sheet .nav { @apply flex-row justify-start gap-3 rounded-[12px] px-3.5 py-3 text-[15px]; }
  .more-sheet .nav.is-on { background: var(--surface-2); box-shadow: inset 3px 0 0 var(--accent); }
  .scrim { @apply fixed inset-0 z-40; background: rgba(20, 25, 24, 0.18); }

  @media (min-width: 900px) {
    .shell { @apply grid-cols-[212px_1fr]; }
    .top { @apply col-span-full flex-row items-baseline gap-5 px-7 py-3.5; }
    .status { @apply ml-auto text-[13px]; }
    .rail {
      @apply sticky flex flex-col gap-0.5 px-3 py-4;
      border-right: 1px solid var(--line-warm);
      top: 57px; height: calc(100dvh - 57px);
    }
    .rail .nav { @apply flex-row justify-start gap-3 rounded-[12px] px-3.5 py-2.5 text-[15px]; }
    .rail .nav.is-on { @apply text-ink; background: var(--surface); box-shadow: var(--shadow), inset 3px 0 0 var(--accent); }
    .rail .nav .badge { @apply static ml-auto; }
    .rail .nav.secondary { @apply text-faint; }
    .rail .nav.secondary.is-on { @apply text-ink; }
    .rail-gap { @apply h-5; }
    .bar, .more-sheet, .scrim { @apply hidden; }
    main { @apply px-10 pt-8 pb-20; }
  }

  .badge {
    @apply inline-flex min-w-[18px] items-center justify-center rounded-full px-1.5 text-[11px] font-semibold leading-[18px] text-white;
    background: var(--badge);
  }

  /* ---- text ---- */
  .headline { @apply mb-2 mt-0 text-[24px] font-semibold leading-[1.25] tracking-[-0.02em]; }
  .headline.small { @apply text-[15px] font-medium text-muted; }
  .headline.muted { @apply text-[15px] font-medium text-muted; }
  .note { @apply mb-4 mt-0 text-[13px] leading-[1.6] text-muted; }
  .faint { color: var(--faint); }
  .muted { color: var(--muted); }
  .error { color: var(--secret); }
  .empty { @apply m-0 py-8 text-muted; }
  .group-title { @apply mt-9 mb-3 text-[15px] font-semibold tracking-[-0.01em] text-ink; }

  /* ---- cards and rows ---- */
  /* On the cream ground a white card is already a card; a border on top of
     that is a second way of saying the same thing. */
  .card { @apply rounded-card bg-surface; box-shadow: var(--shadow); }
  .rows { @apply m-0 list-none p-0; }
  .rows.cards { @apply flex flex-col gap-4; }
  /* A list is one white panel with dividers inside it, not bare rules on
     the page: the page is the cream ground, and content sits on paper. */
  .rows.panel { @apply overflow-hidden rounded-card bg-surface; box-shadow: var(--shadow); }
  .rows.panel > .row { @apply px-5; }
  .rows.panel > .row:last-child { border-bottom: 0; }
  .row { @apply border-b border-line py-4; }
  .rows.compact .row { @apply py-3; }
  .rows.cards > .row { @apply rounded-card bg-surface px-5 py-4; box-shadow: var(--shadow); }
  .rows.cards > .row:hover { box-shadow: var(--shadow-lift); }
  .meta { @apply flex flex-wrap items-baseline gap-x-2.5 gap-y-1 text-[13px] text-muted; }
  .who { @apply font-medium text-ink; }
  .thread { color: var(--faint); }
  .preview { @apply mt-1 cursor-pointer; overflow-wrap: anywhere; }
  .preview.static { cursor: default; }
  .row.is-open > .preview:not(.static) { color: var(--muted); }
  button.preview, .row-head { @apply block w-full border-0 bg-transparent p-0 text-left leading-[inherit] text-inherit; }
  .row-head { cursor: pointer; }
  .row-head .preview { @apply mt-1; }
  .excerpt { @apply my-1.5 whitespace-pre-wrap text-[13px]; overflow-wrap: anywhere; }

  .detail {
    @apply mt-3 rounded-[14px] border px-5 py-4;
    border-color: color-mix(in srgb, var(--line) 70%, transparent);
    background: var(--surface-2);
    overflow-wrap: anywhere;
  }
  .detail p { @apply mb-2.5 mt-0 whitespace-pre-wrap; }
  .detail p:last-child { @apply mb-0; }
  .detail .subject { @apply font-semibold; }
  .judgements { @apply mb-2.5 text-[13px] text-muted; }
  .judgements div { @apply py-0.5; }
  .judgements b { @apply font-medium text-ink; }
  .actions-line { @apply my-1.5 flex gap-2; }

  .summary {
    @apply mb-3 rounded-[12px] px-3 py-2.5 text-[13px] text-muted;
    background: var(--surface-2);
    border-left: 3px solid var(--line-strong);
  }
  .summary .ai { @apply mb-1 block text-[11px] font-semibold uppercase tracking-[0.06em]; color: var(--faint); }
  .summary p { @apply m-0 whitespace-pre-wrap; }

  /* A level is a dot and a word (design 06). */
  .level { @apply inline-flex items-center gap-1.5 rounded-full px-2 py-px text-[11px] font-medium tracking-[0.02em]; cursor: help; }
  .level::before { content: ""; @apply h-[7px] w-[7px] rounded-full; background: currentColor; }
  .level-public { color: var(--public); background: color-mix(in srgb, var(--public) 12%, transparent); }
  .level-personal { color: var(--personal); background: color-mix(in srgb, var(--personal) 12%, transparent); }
  .level-secret { color: var(--secret); background: color-mix(in srgb, var(--secret) 12%, transparent); }
  .level-secret::before { border-radius: 2px; }

  /* ---- controls: one button system ---- */
  .chooser { @apply mt-2.5 flex flex-wrap items-center gap-1.5; }
  .choose, .back, .fold, .source, .role.removable, .row-head, button.preview { -webkit-tap-highlight-color: transparent; }
  /* Outlined: a choice among several. */
  .choose {
    @apply inline-flex min-h-[38px] items-center justify-center gap-1.5 rounded-control border border-line bg-surface px-3.5 py-1.5 text-[13px] font-medium text-ink transition-colors;
  }
  .choose:hover { border-color: var(--ink); color: var(--ink); }
  .choose:active { background: var(--surface-2); }
  .choose:disabled { @apply cursor-default opacity-50; }
  .choose.lowers { color: var(--muted); }
  .choose.lowers:hover { color: var(--secret); border-color: var(--secret); }
  /* Filled: the one thing to do here. */
  .choose.primary { @apply border-transparent; background: var(--accent-fill); color: var(--on-accent); }
  .choose.primary:hover { background: var(--accent-fill-deep); color: var(--on-accent); }
  .choose.level-public, .choose.level-personal, .choose.level-secret { background: var(--surface); }
  /* Quiet: link-sized, same shape. */
  .back, .fold {
    @apply inline-flex min-h-[30px] items-center gap-1 rounded-full border border-transparent bg-transparent px-2.5 py-0.5 text-[13px] font-medium text-muted transition-colors;
  }
  .back:hover, .fold:hover { color: var(--ink); background: var(--surface-2); }
  .reason, .role-input, .ask input, .filters input, .filters select, .pair-form input {
    @apply min-h-[38px] rounded-control border border-line bg-surface px-3 py-2;
  }
  .reason { @apply min-w-[180px] flex-1; }
  textarea.draft, textarea.notes {
    @apply w-full min-h-[104px] resize-y rounded-[12px] border border-line px-3.5 py-2.5 text-[15px] leading-[1.6];
    background: var(--surface-2);
  }
  textarea.draft[readonly] { color: var(--muted); }
  .card-label { @apply mb-1 mt-3 text-[11px] font-semibold uppercase tracking-[0.08em]; color: var(--faint); }
  .rationale { @apply m-0; }
  /* An agent's proposal: labelled values, one fixed layout (design 11). */
  .card-fields {
    @apply m-0 grid grid-cols-[minmax(96px,max-content)_1fr] gap-x-4 gap-y-1.5 rounded-[12px] border border-line px-3.5 py-2.5 text-[15px];
    background: var(--surface-2);
  }
  .card-fields dt { color: var(--muted); }
  .card-fields dd { @apply m-0 break-words; }
  .card-fields dd.money { font-variant-numeric: tabular-nums; }

  /* ---- work for executors (design 13) ---- */
  .work-form { @apply flex flex-col gap-2.5; }
  .work-form label { @apply flex flex-col gap-1 text-[13px] text-muted; }
  .work-form label.quiet-toggle { @apply flex-row; }
  .work-form .field, .setup-form .field { @apply flex flex-col gap-1.5; }
  .work-form .field-label, .setup-form .field-label { @apply text-[13px] text-muted; }
  .work-form .field .chooser, .setup-form .field .chooser { @apply mt-0; }
  .work-form .field-note { @apply m-0 text-[12px] leading-[1.5]; color: var(--faint); }
  .work .state.running { color: var(--accent-ink); }
  .work .state.failed { color: var(--secret); }
  .work .state.waiting { color: var(--accent-ink); font-weight: 600; }
  .work .asked {
    @apply mt-3 flex flex-col gap-2 rounded-[14px] border p-4;
    border-color: var(--accent-ink); background: var(--surface-2);
  }
  .work .asked .chooser { @apply mt-0; }
  .work .asked-question { @apply m-0 text-[16px] font-medium; }
  .work .asked .field-note { @apply m-0 text-[12px] leading-[1.5]; color: var(--faint); }
  .work .diff, .work .said {
    @apply m-0 mt-2 max-h-[60vh] overflow-auto whitespace-pre-wrap rounded-[12px] border border-line px-3.5 py-2.5 text-[12px] leading-[1.5];
    background: var(--surface-2);
  }
  .work .said { @apply list-none text-[13px]; }
  .work .said li { @apply border-b border-line py-1; }
  .work .said li:last-child { border-bottom: 0; }
  .work .said-thought { color: var(--muted); }
  .work .said-asked { color: var(--muted); font-style: italic; }

  /* ---- categories (design 06) ---- */
  .quiet-toggle { @apply flex items-center gap-1.5 text-[13px] text-muted; white-space: nowrap; }
  .action .quiet-toggle { white-space: normal; }
  .quiet-toggle input[type="checkbox"] { @apply w-auto flex-none; }
  .quiet-note { @apply mx-5 mb-0 mt-2; }
  .quiet-senders { @apply px-5; }
  .category-chooser .choose { @apply px-3 py-1 text-[13px]; }
  /* ---- junk (design 06) ---- */
  .junk-row { @apply mt-4 border-t border-line pt-3; }
  .junk-ask { @apply flex flex-col items-end gap-1.5 text-right; max-width: 22rem; }
  /* ---- agents (design 11) ---- */
  .avatar.agent { color: var(--ink); }
  .linkish { @apply p-0 text-left; background: none; border: 0; cursor: pointer; }
  .linkish:hover { text-decoration: underline; }
  .risk.outward, .risk.strangers { color: var(--accent-ink); }
  .risk-badge { @apply shrink-0 rounded-full border px-2.5 py-0.5 text-[12px]; border-color: var(--line); color: var(--muted); }
  .risk-badge.outward, .risk-badge.strangers { border-color: var(--accent-ink); color: var(--accent-ink); }
  .agent-preview { @apply mt-2 flex flex-col gap-2 rounded-[12px] border border-line p-4; }
  .preview-head { @apply flex items-center gap-3; }
  .preview-purpose { @apply m-0 text-[15px]; }
  .card-fields.grants { @apply text-[14px]; }
  .tried { @apply m-0 flex list-none flex-col gap-2 p-0; }
  .tried-head { @apply text-[14px]; }
  .tried-draft { @apply m-0 whitespace-pre-wrap rounded-[12px] border border-line px-3 py-2 text-[14px]; background: var(--surface-2); }
  .trial-log pre { @apply m-0 mt-1 max-h-48 overflow-auto whitespace-pre-wrap text-[12px]; color: var(--muted); }
  .hidden-file { display: none; }
  label.choose { cursor: pointer; }
  .bubble.failed { color: var(--muted); font-style: italic; }
  .composer-input {
    @apply min-h-[40px] min-w-0 flex-1 rounded-full border border-line bg-surface px-4 py-2 text-[15px];
  }

  /* ---- sources ---- */
  .sources { @apply mt-1.5 flex flex-wrap gap-x-2.5 gap-y-1.5; }
  .source-wrap { display: contents; }
  .source {
    @apply rounded-full border border-line bg-surface px-2.5 py-0.5 text-left text-[13px] text-muted transition-colors;
  }
  .source:hover { color: var(--ink); border-color: var(--ink); }
  .source-wrap .detail { flex-basis: 100%; }

  /* ---- today ---- */
  .points { @apply m-0 list-none p-0; }
  .point { @apply border-b border-line px-5 py-3.5; }
  .point:last-child { border-bottom: 0; }
  .point .text { @apply block; }
  .point.unfounded .text { color: var(--muted); }
  .point.empty-point { @apply text-[13px] text-muted; }
  .digest-card { @apply mb-5 overflow-hidden; }
  .digest-card .group-title { @apply mt-0 mb-0 px-5 pt-5 pb-2 text-[15px]; }
  .digest-card .point:last-child { border-bottom: 0; }

  /* Design 06 opens on Today, and this is the first thing on it: the one
     place the page speaks in full colour, so that the day has a face. The
     field is deeper than the brand so that text dimmed for hierarchy still
     clears 4.5:1 on it. */
  .hero {
    @apply mb-10 rounded-card px-6 py-6;
    background: linear-gradient(135deg, var(--hero-from), var(--hero-to) 92%);
    color: var(--on-hero);
    box-shadow: var(--shadow-lift);
  }
  @media (min-width: 900px) { .hero { @apply px-8 py-7; } }
  /* A single seal in the corner of the wash, as a painting is signed. */
  .hero { position: relative; }
  .hero::after {
    content: ""; position: absolute; top: 24px; right: 24px;
    width: 12px; height: 12px; border-radius: 2px; background: var(--accent);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent);
  }
  .hero-eyebrow { @apply m-0 text-[11px] font-semibold uppercase tracking-[0.1em]; opacity: 0.8; }
  .hero-line { @apply mt-1.5 mb-0 text-[24px] font-semibold leading-[1.25] tracking-[-0.02em]; }
  .hero-foot { @apply mt-2 mb-0 text-[13px]; opacity: 0.8; }
  /* The day's numbers: four frosted tiles inside the field, each a figure
     and what it counts, always all four so the card keeps its shape. */
  .hero-stats { @apply mt-5 grid grid-cols-2 gap-2.5; }
  @media (min-width: 640px) { .hero-stats { @apply grid-cols-4; } }
  .hero-stat {
    @apply flex flex-col gap-0.5 rounded-[14px] px-4 py-3;
    background: color-mix(in srgb, var(--on-hero) 13%, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--on-hero) 20%, transparent);
  }
  .hero-stat-n { @apply text-[24px] font-semibold leading-[1.1] tracking-[-0.02em]; }
  .hero-stat-label { @apply text-[13px]; opacity: 0.85; }
  .hero-stat.zero .hero-stat-n { opacity: 0.55; }
  .commitment .standing { @apply text-[13px] text-muted; }
  .commitment.overdue .preview { color: var(--secret); }

  /* ---- timeline ---- */
  .filters { @apply mb-3 flex flex-wrap gap-2; }
  .filters input[type="search"] { @apply flex-[1_1_200px]; }
  .filters select { @apply flex-[0_1_auto]; }

  /* ---- actions ---- */
  .action { position: relative; }
  .rows.cards > .action.pending { box-shadow: var(--shadow-lift), inset 0 0 0 1px var(--accent-line); }
  .action.executed .who::after { content: " · ✓"; color: var(--public); }
  .action.failed .who::after, .action.unknown .who::after { content: " · !"; color: var(--secret); }

  /* ---- ask ---- */
  .turns { @apply m-0 mb-4 flex list-none flex-col gap-4 p-0; }
  .turn { @apply rounded-[16px] px-4 py-3; }
  .turn.question { @apply self-end max-w-[85%] text-ink; background: var(--surface-2); border: 1px solid var(--line); border-bottom-right-radius: 6px; }
  .turn.answer { @apply bg-surface; box-shadow: var(--shadow); border-bottom-left-radius: 6px; }
  .answer-text { @apply mb-1.5 mt-0 whitespace-pre-wrap; }
  .answer-text.stopped { color: var(--muted); }
  .ask {
    @apply sticky flex gap-2 py-2;
    bottom: calc(var(--bar-h) + var(--safe-b));
    background: color-mix(in srgb, var(--bg) 85%, transparent);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
  }
  @media (min-width: 900px) { .ask { bottom: 0; } }
  .ask input { @apply flex-1 rounded-full px-4 text-[15px]; }
  .ask .choose { @apply rounded-full px-4; }
  .record .step { @apply my-0.5 whitespace-pre-wrap text-[13px] text-muted; }
  .record .step time { @apply mr-1.5; color: var(--faint); }

  /* ---- shared by conversations ---- */
  .avatar {
    @apply inline-flex h-10 w-10 flex-none items-center justify-center rounded-full text-[13px] font-semibold;
    background: linear-gradient(140deg, var(--accent-fill), var(--accent-fill-deep));
    color: var(--on-accent);
  }
  .avatar.multi {
    @apply rounded-[12px];
    background: var(--surface-2); box-shadow: inset 0 0 0 1px var(--line-strong);
    color: var(--ink);
  }
  .avatar.small { @apply h-7 w-7 text-[11px]; }
  .role { @apply rounded-full border-0 px-2 py-0.5 text-[11px] font-medium; background: var(--surface-2); color: var(--muted); box-shadow: inset 0 0 0 1px var(--line); }
  /* Design 14: which workspace an account or a task is in. */
  .space-chip { @apply mr-1.5 align-middle; }
  .account-name .space-chip { @apply ml-1.5 mr-0; }
  .task-note { @apply mx-4 mt-1; }

  /* Design 06 v0.7: the admin passphrase, asked for one request. */
  .passphrase-scrim { @apply fixed inset-0 z-[60]; background: rgba(20, 25, 24, 0.28); }
  .passphrase-sheet {
    @apply fixed inset-x-3 top-[18vh] z-[70] mx-auto grid max-w-[420px] gap-3 rounded-card border border-line bg-surface p-5;
    box-shadow: var(--shadow), 0 20px 50px -20px rgba(0,0,0,0.35);
  }
  .passphrase-sheet input { @apply w-full; }
  .admin-news {
    @apply mb-4 flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-card border border-line bg-surface px-4 py-3 text-[14px];
    box-shadow: inset 3px 0 0 var(--line-strong);
  }
  .admin-news.bad { box-shadow: inset 3px 0 0 var(--accent); }
  .admin-news span { @apply flex-1; min-width: 12rem; }
  .device .role { @apply ml-1.5; }
  /* Design 06 v0.14: spaces. */
  .space-cards { @apply mb-5 flex flex-col gap-3; }
  .space-cards .row { @apply border-0 p-0; }
  .space-card { @apply flex w-full flex-col items-start gap-1 rounded-xl px-4 py-3 text-left; background: var(--surface-2); box-shadow: inset 0 0 0 1px var(--line); }
  .space-card:hover { background: var(--surface); }
  .space-title { @apply text-[16px] font-semibold; }
  .space-counts { @apply flex flex-wrap items-center gap-2 text-[13px]; }
  .badge-soft { @apply rounded-full px-2 py-0.5 text-[12px] font-medium; background: var(--surface); box-shadow: inset 0 0 0 1px var(--line); }
  .badge-soft.on { color: var(--public); }
  .space-head { @apply mb-2 mt-1 text-[20px] font-semibold; }
  .space-made .field-label { @apply mt-3 block; }
  /* Design 06 v0.17: a space's overview and its pages. */
  .space-tabs { overflow-x: auto; scrollbar-width: none; }
  .space-tabs .segment { @apply flex-none px-3.5; }
  @media (min-width: 520px) { .space-tabs .segment { @apply flex-1; } }
  .space-stats { @apply mb-2 grid grid-cols-2 gap-2.5; }
  @media (min-width: 640px) { .space-stats { @apply grid-cols-4; } }
  .space-stat { @apply flex flex-col items-start gap-0.5 rounded-[14px] border-0 px-4 py-3 text-left text-ink; background: var(--surface); box-shadow: var(--shadow); }
  .space-stat:hover { background: var(--surface-2); }
  .space-stat-n { @apply text-[24px] font-semibold leading-[1.1] tracking-[-0.02em]; }
  .space-stat-label { @apply text-[13px] text-muted; }
  .space-stat.zero .space-stat-n { opacity: 0.4; }
  .space-stat.hot .space-stat-n { color: var(--accent); }
  .needs .need { @apply text-left; }
  .needs .need.bad { color: var(--secret); }
  .more-link { @apply mt-1 text-[13px]; }
  .todo-row a.who { @apply font-medium text-ink no-underline; }
  .todo-row a.who:hover { text-decoration: underline; }
  .pr-state.merged { color: var(--public); font-weight: 600; }
  .pr-state.closed { color: var(--muted); }
  .gh-line { @apply mt-2; }
  .gh-account p { @apply my-1.5; }
  .gh-account .field-label { @apply mr-1.5 inline; }
  .gh-token { @apply mt-2; }
  .project-line { @apply flex items-center justify-between gap-3; }
  .project-row .setup-form { @apply mt-3; }
  .role.removable { cursor: pointer; }
  .role.removable:hover { text-decoration: line-through; color: var(--secret); }
  .role-input { @apply min-h-[28px] min-w-[100px] border-0 bg-transparent text-[13px]; }
  .roles { @apply mb-1.5 flex flex-wrap items-center gap-1.5; }
  .handles { @apply flex flex-wrap gap-2.5 text-[13px] text-muted; overflow-wrap: anywhere; }
  .handle.inferred { text-decoration: underline dotted; }
  .months { @apply flex h-[30px] items-end gap-[3px]; }
  .month { @apply inline-block w-[10px] rounded-t-[3px]; background: color-mix(in srgb, var(--ink) 22%, var(--surface)); }
  .month.now { background: var(--ink); }

  /* ---- chats: the list ---- */
  .chats-pane { @apply grid max-w-none grid-cols-1 gap-6; }
  .chats-pane.has-detail .chat-list { @apply hidden; }
  .chat-search {
    @apply mb-3 flex items-center gap-2 rounded-full bg-surface px-4;
    box-shadow: var(--shadow); color: var(--faint);
  }
  .chat-search input { @apply min-h-[42px] flex-1 border-0 bg-transparent text-[15px] text-ink outline-none; }
  .parties { @apply m-0 flex list-none flex-col gap-1 p-0; }
  .segments { @apply mb-3 flex gap-1 rounded-full bg-surface p-1; box-shadow: var(--shadow); }
  .segment {
    @apply flex min-h-[36px] flex-1 items-center justify-center gap-1.5 rounded-full border-0 bg-transparent px-3 text-[14px] font-medium text-muted;
  }
  .segment.is-on { background: var(--ink); color: var(--surface); }
  .segment-count { @apply rounded-full px-1.5 text-[11px] font-semibold; background: var(--accent); color: var(--surface); }
  .parties-divider { @apply px-3 pb-1 pt-4 text-[12px] font-medium uppercase tracking-wide; color: var(--faint); }
  .task-party.done .party-name { @apply font-medium text-muted line-through; text-decoration-color: var(--faint); }
  .party-when.due { color: var(--accent); }
  .task-status { @apply rounded-full px-2 py-0.5 text-[12px] font-semibold; background: color-mix(in srgb, var(--accent) 14%, var(--surface)); color: var(--accent); }
  .task-status.done { background: var(--surface-2); color: var(--muted); }
  .task-description { @apply whitespace-pre-wrap text-[14px]; overflow-wrap: anywhere; }
  .party {
    @apply flex w-full items-center gap-3.5 rounded-card border-0 bg-transparent px-3 py-3 text-left transition-colors;
  }
  .party:hover { background: color-mix(in srgb, var(--surface) 70%, transparent); }
  .party.is-on { background: var(--surface); box-shadow: var(--shadow), inset 3px 0 0 var(--accent); }
  .party-body { @apply flex min-w-0 flex-1 flex-col gap-0.5; }
  .party-top { @apply flex items-baseline justify-between gap-3; }
  .party-name { @apply truncate font-semibold; }
  .party-when { @apply flex-none text-[11px]; color: var(--faint); }
  .party-last { @apply truncate text-[13px] text-muted; }
  .party-last b { @apply font-medium text-ink; }
  .party-roles { @apply mt-0.5 flex flex-wrap gap-1; }
  @media (min-width: 900px) {
    .chats-pane { @apply grid-cols-[minmax(260px,330px)_minmax(0,1fr)] items-start; }
    .chats-pane.has-detail .chat-list { @apply block; }
    .chat-list { @apply sticky overflow-auto pr-1; top: 76px; max-height: calc(100dvh - 100px); }
  }

  /* ---- chats: one conversation ---- */
  .conversation {
    @apply flex min-w-0 flex-col overflow-hidden rounded-card bg-surface;
    box-shadow: var(--shadow-lift);
  }
  .conv-head { @apply flex items-center gap-3 px-4 py-3; border-bottom: 1px solid var(--line); }
  @media (min-width: 900px) {
    .conv-head { @apply px-6 py-4; }
    .conv-head > .back:first-child { @apply hidden; }
  }
  .conv-title { @apply flex min-w-0 flex-1 flex-col; }
  .conv-name { @apply truncate text-[18px] font-semibold tracking-[-0.01em]; }
  .conv-sub { @apply flex flex-wrap items-center gap-1.5 text-[13px]; }
  .conv-toggle { @apply flex-none; }
  .chev { @apply inline-flex transition-transform; }
  .chev.up { transform: rotate(180deg); }
  .conv-summary {
    @apply flex flex-wrap items-center gap-x-4 gap-y-1.5 px-4 py-2.5 text-[13px] text-muted;
    background: var(--surface-2); border-bottom: 1px solid var(--line);
  }
  .conv-summary b { @apply font-semibold text-ink; }
  @media (min-width: 900px) { .conv-summary { @apply px-6; } }
  .promise-chip {
    @apply ml-auto rounded-full border-0 px-3 py-1 text-[13px] font-medium;
    background: transparent; color: var(--faint);
  }
  .promise-chip.has { background: var(--accent-soft); color: var(--accent-ink); }
  .conv-details {
    @apply overflow-auto px-4 pb-4;
    max-height: 45%; background: var(--surface-2); border-bottom: 1px solid var(--line);
  }
  .conv-details .group-title { @apply mt-4 mb-2 text-[13px]; }
  .details-grid { @apply grid grid-cols-1 gap-x-8; }
  @media (min-width: 900px) {
    .conv-details { @apply px-6; }
    .details-grid { @apply grid-cols-2; }
  }

  .stream {
    @apply flex-1 overflow-y-auto px-3 py-4;
    background: color-mix(in srgb, var(--bg) 55%, var(--surface));
    overscroll-behavior: contain;
  }
  @media (min-width: 900px) { .stream { @apply px-6; } }
  .stream-top { @apply mb-2 flex justify-center text-[13px]; }
  .day { @apply my-4 flex justify-center; }
  .day span {
    @apply rounded-full px-3 py-0.5 text-[11px] font-medium;
    background: color-mix(in srgb, var(--surface) 80%, transparent); color: var(--muted);
    box-shadow: 0 0 0 1px var(--line);
  }
  .msg { @apply mt-3 flex flex-col items-start; }
  .msg.tight { @apply mt-1; }
  .msg.mine { @apply items-end; }
  .msg-author { @apply mb-1 px-3 text-[12px] font-semibold; color: var(--muted); }
  .msg:not(.mine):has(.msg-author) { @apply mt-4; }
  .bubble {
    @apply max-w-[82%] rounded-[18px] px-3.5 py-2.5 bg-surface;
    border-bottom-left-radius: 6px; box-shadow: var(--shadow);
  }
  @media (min-width: 900px) { .bubble { @apply max-w-[70%]; } }
  .msg.mine .bubble {
    background: var(--accent-fill); color: var(--on-accent);
    border-bottom-left-radius: 18px; border-bottom-right-radius: 6px;
  }
  .bubble.mail { border-top: 3px solid var(--line-strong); }
  .msg.mine .bubble.mail { border-top-color: color-mix(in srgb, var(--on-accent) 35%, transparent); }
  .bubble-subject { @apply mb-1 mt-0 text-[13px] font-semibold; }
  .bubble-text { @apply m-0 whitespace-pre-wrap text-[15px] leading-[1.5]; overflow-wrap: anywhere; }
  .bubble-text.clamped { display: -webkit-box; -webkit-line-clamp: 9; -webkit-box-orient: vertical; overflow: hidden; }
  .bubble-foot { @apply mt-1 flex items-center justify-end gap-3; }
  .msg-time { @apply text-[11px]; color: var(--faint); }
  .msg.mine .msg-time { color: color-mix(in srgb, var(--on-accent) 78%, transparent); }
  .bubble-more {
    @apply rounded-full border-0 bg-transparent px-1.5 text-[11px] font-medium;
    color: var(--muted);
  }
  .msg.mine .bubble-more { color: var(--on-accent); }
  .bubble-item { @apply mt-2 flex flex-wrap items-center gap-2 pt-2 text-[11px]; border-top: 1px solid var(--line); }
  .msg.mine .bubble-item { border-top-color: color-mix(in srgb, var(--on-accent) 30%, transparent); }
  .msg.mine .bubble .summary { color: var(--ink); }
  .stream-drafts { @apply mt-5; }
  /* An approved action on its way: a quiet pulse, so the card is plainly
     still waiting on the connector and not stuck. */
  .note.sending { @apply m-0; animation: sending 1.6s ease-in-out infinite; }
  @keyframes sending { 50% { opacity: 0.45; } }
  @media (prefers-reduced-motion: reduce) { .note.sending { animation: none; } }
  .speakers { @apply m-0 flex list-none flex-col gap-2 p-0; }
  .speaker { @apply grid items-center gap-3 text-[13px]; grid-template-columns: auto minmax(0, 9rem) 1fr auto; }
  .speaker-name { @apply truncate; }
  .speaker-bar { @apply h-1.5 overflow-hidden rounded-full; background: var(--line); }
  .speaker-bar span { @apply block h-full rounded-full; background: var(--ink); }

  .composer {
    @apply flex flex-wrap items-center gap-3 px-4 py-3;
    border-top: 1px solid var(--line); background: var(--surface);
  }
  @media (min-width: 900px) { .composer { @apply px-6; } }
  .composer .choose { @apply rounded-full px-4; }
  .composer-note { @apply min-w-0 flex-1 text-[13px] text-muted; }

  /* ---- records ---- */
  .payload {
    @apply mt-2 max-h-[260px] overflow-auto rounded-[12px] border border-line px-3 py-2.5 font-mono text-[13px] leading-[1.5] whitespace-pre-wrap break-words;
    background: var(--surface-2);
  }

  /* ---- settings ---- */
  .settings .section { @apply mb-4 rounded-card bg-surface px-5 py-5; box-shadow: var(--shadow); }
  .settings .section .group-title { @apply mt-0 mb-2; }
  .accounts { @apply m-0 list-none p-0 text-[15px]; }
  .account { @apply flex flex-wrap gap-3 border-b border-line py-1.5; }
  .account:last-child { border-bottom: 0; }
  .account .address { @apply font-semibold; }
  .account .state { color: var(--muted); }
  .account.needs_login .state, .account.stopped .state { color: var(--secret); }
  .devices { @apply m-0 mb-3 list-none p-0; }
  .device { @apply flex flex-wrap items-center gap-3 border-b border-line py-2; }
  .device:last-child { border-bottom: 0; }
  .device.revoked { color: var(--faint); }
  .device-name { @apply flex-1 font-medium; }
  .pairing { @apply mt-2; }
  .pair-url { @apply m-0 font-mono text-[13px] text-muted; overflow-wrap: anywhere; }
  .pair-code { @apply my-2 inline-block rounded-[14px] px-4 py-2 font-mono text-[34px] font-semibold leading-[1.2] tracking-[0.14em] text-ink; background: var(--surface-2); box-shadow: inset 0 0 0 1px var(--line); }
  .qr { @apply my-2 w-[200px] max-w-full rounded-[12px] bg-white p-2; box-shadow: var(--shadow); }
  .qr svg { @apply block h-auto w-full; }
  .facts { @apply m-0 grid gap-x-4 gap-y-1 text-[15px]; grid-template-columns: max-content 1fr; }
  .facts dt { color: var(--muted); }
  .facts dd { @apply m-0; overflow-wrap: anywhere; }
  .pair-form { @apply grid max-w-[360px] gap-3; }

  /* ---- welcome ---- */
  .welcome { @apply mx-auto flex max-w-[620px] flex-col gap-4; }
  .welcome-top { @apply flex items-center justify-between; }
  .welcome-steps { @apply m-0 flex list-none gap-1.5 p-0; }
  .welcome-steps li { @apply h-1.5 w-8 rounded-full; background: var(--line); }
  .welcome-steps li.done { background: var(--line-strong); }
  .welcome-steps li.on { background: var(--accent); }
  .welcome-card { @apply flex flex-col items-start gap-3 rounded-card bg-surface px-6 py-7; box-shadow: var(--shadow-lift); }
  .welcome-mark {
    @apply inline-flex h-14 w-14 items-center justify-center rounded-[16px];
    background: linear-gradient(140deg, var(--hero-from), var(--hero-to)); color: var(--on-hero);
  }
  .welcome-lede { @apply m-0 text-[15px] leading-[1.65]; }
  .consent { @apply m-0 flex list-none flex-col gap-2.5 p-0; }
  .consent li { @apply rounded-[12px] px-4 py-3 text-[14px]; background: var(--surface-2); border: 1px solid var(--line); }
  .consent b { @apply font-semibold; color: var(--ink); }
  .checks { @apply m-0 flex w-full list-none flex-col gap-1 p-0; }
  .checks li { @apply flex items-center gap-3 py-2; border-bottom: 1px solid var(--line); }
  .checks li:last-child { border-bottom: 0; }
  .check-mark { @apply inline-flex h-7 w-7 flex-none items-center justify-center rounded-full text-[13px] font-semibold; }
  .checks li.ok .check-mark { background: color-mix(in srgb, var(--public) 16%, transparent); color: var(--public); }
  .checks li.bad .check-mark { background: color-mix(in srgb, var(--secret) 16%, transparent); color: var(--secret); }
  .checks li.warn .check-mark { background: var(--surface-2); color: var(--muted); box-shadow: inset 0 0 0 1px var(--line-strong); }
  .check-body { @apply flex flex-col; }
  .check-name { @apply font-medium; }

  /* ---- export and delete ---- */
  .choose.danger { color: var(--secret); border-color: color-mix(in srgb, var(--secret) 45%, var(--line)); }
  .choose.danger:hover:not(:disabled) { background: var(--secret); color: #fff; border-color: var(--secret); }
  .erased { @apply rounded-[14px] px-4 py-3; background: var(--surface-2); }

  /* ---- accounts and models ---- */
  .account-list, .model-list { @apply m-0 mb-3 list-none p-0; }
  .account-row, .model-row { @apply flex items-center gap-3 py-2.5; border-bottom: 1px solid var(--line); }
  .account-row:last-child, .model-row:last-child { border-bottom: 0; }
  .account-icon {
    @apply inline-flex h-9 w-9 flex-none items-center justify-center rounded-[10px];
    background: var(--surface-2); color: var(--ink); box-shadow: inset 0 0 0 1px var(--line);
  }
  .account-body, .model-body { @apply flex min-w-0 flex-1 flex-col; }
  .account-name, .model-name { @apply truncate font-medium; }
  .account-state { @apply truncate text-[13px] text-muted; }
  .account-state.ok { color: var(--public); }
  .account-state.bad { color: var(--secret); }
  .ok-note { color: var(--public); }
  .choose.is-on { border-color: var(--ink); color: var(--ink); background: var(--surface-2); }
  .setup-form {
    @apply mt-3 grid max-w-[460px] gap-3 rounded-[14px] p-4;
    background: var(--surface-2); border: 1px solid var(--line);
  }
  .setup-form label { @apply grid gap-1 text-[13px] text-muted; }
  .setup-form input, .setup-form select {
    @apply min-h-[40px] rounded-control border border-line bg-surface px-3 text-[15px] text-ink;
  }
  .setup-form .field-note.error { color: var(--secret); }
  .help { @apply rounded-[12px] px-3.5 py-3 text-[13px]; background: var(--surface); box-shadow: inset 0 0 0 1px var(--line); }
  .help-title { @apply m-0 mb-1 font-medium text-ink; }
  .help ol { @apply m-0 pl-5; }
  .help a { color: var(--ink); text-decoration: underline; text-decoration-color: var(--accent); text-underline-offset: 3px; }
  .steps { @apply m-0 flex list-none flex-wrap gap-2 p-0 text-[13px]; }
  .steps li { @apply rounded-full px-3 py-1; background: var(--surface); color: var(--faint); box-shadow: 0 0 0 1px var(--line); }
  .steps li.on { background: var(--accent-soft); color: var(--accent-ink); box-shadow: 0 0 0 1px var(--accent-line); }
  .steps li.done { color: var(--public); }
